export function minStackOperations(operations: (string | number)[][]): (number | null)[] {
  const values:number[]=[], minimums:number[]=[], result:(number|null)[]=[]; for(const operation of operations) { const name=operation[0]; if(name==='push') { const value=operation[1] as number; values.push(value); minimums.push(Math.min(value,minimums[minimums.length-1]??Infinity)); result.push(null); } else if(name==='pop') { values.pop(); minimums.pop(); result.push(null); } else result.push(name==='top'?values[values.length-1]:minimums[minimums.length-1]); } return result;
}
